def dump(p,x):p.parent.mkdir(exist_ok=True,parents=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def AND(*args):return {'op':'and','args':list(args)}
def eq(field,value):return {'op':'eq','field':field,'value':value}
def any_(field,arg):return {'op':'any','field':field,'arg':arg}
def enemy(id,move=None,index=None,power=None):
 a=[eq('enemy.id',id),eq('enemy.alive',True)]
 if move:a.append(eq('enemy.move_id',move))
 if index is not None:a.append(eq('enemy.index',index))
 if power:a.append({'op':'gt','field':'enemy.powers.'+power,'value':0})
 return any_('enemies.items',AND(*a))
def hand(id):return any_('player.hand',AND(eq('card.id',id),eq('card.can_play',True)))
def action(id,target=None):
 a=[eq('action.kind','card'),eq('card.id',id)]
 if target is not None:a.append(eq('action.target',target))
 return any_('option.actions',AND(*a))
